from demo_kit import build
import json

# All descriptions below are short original study summaries, not translations.
def rec(id,name,group,summary,detail,ref,url,**kw):
    return dict(id=id,name=name,group=group,summary=summary,detail=detail,ref=ref,url=url,**kw)
def q(ref):return 'https://quran.com/'+ref.replace(':','/')
def b(n):return 'https://sunnah.com/bukhari:'+str(n)
CSS='''
.explore-visual{background:#edf4fa;border:1px solid #b7cedc;border-radius:12px;overflow:hidden;margin:18px 0}.explore-visual svg{display:block;width:100%}.explore-visual text{font:14px 'Segoe UI',sans-serif;fill:#172c37}.explore-visual .node{cursor:pointer}.explore-visual .node:hover circle{stroke:#946119;stroke-width:4}.record-list{display:grid;gap:9px;max-height:460px;overflow:auto;padding:5px}.record-list button{text-align:left;background:#f3f7fa;color:#172c37;border-color:#c8d7dd}.record-list small{display:block}.record-list button[aria-pressed=true]{background:#deedf5}.evidence-panel{background:#f5f9fc;border-top:5px solid #346a91;padding:22px;border-radius:9px}.evidence-panel h2{font-size:27px}.note-label{font-size:12px;text-transform:uppercase;letter-spacing:1px;font-weight:700;color:#345b75}.link-buttons{display:flex;gap:8px;flex-wrap:wrap}.link-buttons button{padding:7px 10px;font-size:14px}.stats-line{display:flex;gap:20px;flex-wrap:wrap;font-size:14px;color:#526873}.context-flow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.context-flow article{border:1px solid #bad0df;border-radius:10px;padding:15px;background:#fff}.context-flow b{display:block;color:#346a91}.bookmark-message{font-size:13px;color:#526873}@media(max-width:650px){.context-flow{grid-template-columns:1fr}.record-list{max-height:280px}.explore-visual text{font-size:15px}}
'''
SCRIPT=r'''
const records=CONFIG.records;let selected=records[0].id;let saved=store.get(CONFIG.slug+'-saved',[]);if(!Array.isArray(saved))saved=[];let visible=[];
$('#filter').innerHTML='<option value="">All '+esc(CONFIG.groupLabel)+'</option>'+[...new Set(records.map(r=>r.group))].map(g=>'<option>'+esc(g)+'</option>').join('');
function matches(r){const query=$('#search').value.trim().toLowerCase();return (!$('#filter').value||r.group===$('#filter').value)&&(!$('#savedOnly').checked||saved.includes(r.id))&&[r.name,r.summary,r.detail,r.ref,r.group].join(' ').toLowerCase().includes(query)}
function choose(id){selected=id;render()}
function svgNode(r,x,y,label){return `<g class="node" data-pick="${esc(r.id)}"><circle cx="${x}" cy="${y}" r="${r.id===selected?16:11}" fill="${r.id===selected?'#946119':'#346a91'}" stroke="white" stroke-width="3"/><text x="${x}" y="${y+34}" text-anchor="middle">${esc(label||r.name)}</text></g>`}
function draw(){let out='';if(!visible.length){$('#visual').innerHTML='<p style="padding:20px">No records match. Clear the search or use Reset filters.</p>';return}
if(CONFIG.mode==='timeline') {out='<path d="M55 90H745" stroke="#8aa9c1" stroke-width="4"/>';visible.forEach((r,i)=>{const x=visible.length===1?400:65+i*670/(visible.length-1);out+=svgNode(r,x,90,r.short||r.name)+`<text x="${x}" y="57" text-anchor="middle">${esc(r.date)}</text>`});out='<svg viewBox="0 0 800 180" role="img" aria-label="Event order, evenly spaced rather than a calendar scale">'+out+'</svg>'}
else if(CONFIG.mode==='map'){out='<rect width="800" height="380" fill="#e3eff8"/><path d="M50 60L300 50 350 150 440 200 530 315 710 325 650 245 560 135 450 75 250 25" fill="#d7e4d7" stroke="#9bb49c"/><text x="50" y="350">Regional schematic • no borders • positions approximate</text>';visible.filter(r=>r.x).forEach(r=>out+=svgNode(r,r.x,r.y,r.short));const unknown=visible.filter(r=>!r.x);if(unknown.length)out+='<rect x="25" y="238" width="210" height="90" rx="8" fill="white" stroke="#9bb4c5" stroke-dasharray="5 5"/><text x="40" y="258">Unlocated in text</text>';unknown.forEach((r,i)=>out+=svgNode(r,120+i*180,275,r.short));out='<svg viewBox="0 0 800 380" role="img" aria-label="Schematic of selected regions; unknown places appear separately">'+out+'</svg>'}
else if(CONFIG.mode==='context'){const r=records.find(r=>r.id===selected);out='<div class="context-flow"><article><b>Text</b>'+esc(r.ref)+'</article><article><b>Reported setting</b>'+esc(r.summary)+'</article><article><b>Evidence</b>'+esc(r.evidence||'Direct report in Sahih al-Bukhari')+'</article></div>'}
else if(CONFIG.mode==='chains'){const paths=CONFIG.paths.filter(p=>!$('#chain').value||p.id===$('#chain').value);out='<svg viewBox="0 0 950 490" role="img" aria-label="Two transmission paths; arrows move from source narrator toward compiler">';paths.forEach((p,row)=>{const y=paths.length===1?200:100+row*230;out+=`<text x="30" y="${y-55}">${esc(p.label)}</text>`;p.ids.forEach((id,i)=>{let r=records.find(r=>r.id===id);let x=50+i*118;if(i)out+=`<path d="M${x-102} ${y}H${x-17}" stroke="#8aa9c1" stroke-width="3" marker-end="url(#arrow)"/>`;out+=svgNode(r,x,y,r.short)})});out+='<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#8aa9c1"/></marker></defs></svg>'}
else {const center=records.find(r=>r.id===selected),ns=visible.filter(r=>r.id!==selected);out='<svg viewBox="0 0 800 420" role="img" aria-label="Selected item and its reviewed relationships">';let peers=CONFIG.edges.filter(e=>e.a===selected||e.b===selected);ns.forEach((r,i)=>{const angle=-Math.PI/2+i*2*Math.PI/Math.max(ns.length,1),x=400+280*Math.cos(angle),y=205+135*Math.sin(angle);const edge=peers.find(e=>(e.a===r.id||e.b===r.id));out+=`<path d="M400 205L${x} ${y}" stroke="${edge?'#346a91':'#c8d7dd'}" stroke-width="${edge?3:1}" ${edge?'':'stroke-dasharray="4 6"'}/>`+svgNode(r,x,y,r.short);});out+=svgNode(center,400,205,center.short||center.name)+'</svg>'}$('#visual').innerHTML=out;$$('[data-pick]').forEach(el=>el.onclick=()=>choose(el.dataset.pick));}
function render(){visible=records.filter(matches);if(!visible.some(r=>r.id===selected))selected=visible[0]?.id;$('#count').textContent=visible.length+' of '+records.length+' records';$('#records').innerHTML=visible.map(r=>`<button type="button" data-id="${esc(r.id)}" aria-pressed="${r.id===selected}">${esc(r.name)}<small>${esc(r.date||r.group)} · ${esc(r.ref)}</small></button>`).join('')||'<p>No matching records. Reset filters to start again.</p>';$$('[data-id]').forEach(el=>el.onclick=()=>choose(el.dataset.id));const r=records.find(r=>r.id===selected);if(!r){$('#detail').innerHTML='<h2>No selection</h2><p>Change the filters to see a record.</p>';draw();return}let relations=(CONFIG.edges||[]).filter(e=>e.a===r.id||e.b===r.id);$('#detail').innerHTML=`<div class="note-label">${esc(r.group)}${r.date?' · '+esc(r.date):''}</div><h2>${esc(r.name)}</h2><p>${esc(r.summary)}</p><p>${esc(r.detail)}</p>${r.limit?'<div class="notice">'+esc(r.limit)+'</div>':''}<p class="source"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Read ${esc(r.ref)}</a>${r.extra?' · <a href="'+esc(r.extra)+'" target="_blank" rel="noopener noreferrer">Related source</a>':''}</p>${relations.length?'<h3>Connections and evidence</h3><ul>'+relations.map(e=>{let other=records.find(x=>x.id===(e.a===r.id?e.b:e.a));return '<li><button class="secondary" type="button" data-related="'+esc(other.id)+'">'+esc(other.name)+'</button><p>'+esc(e.label)+' <a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">Evidence</a></p></li>'}).join('')+'</ul>':''}<button type="button" id="save" class="secondary">${saved.includes(r.id)?'Remove saved record':'Save record on this device'}</button><p class="bookmark-message" id="storageMessage"></p>`;$('#save').onclick=()=>{saved=saved.includes(r.id)?saved.filter(id=>id!==r.id):[...saved,r.id];const ok=store.set(CONFIG.slug+'-saved',saved);render();if(!ok&&$('#storageMessage'))$('#storageMessage').textContent='Browser storage is unavailable. The saved list will last for this session only.'};$$('[data-related]').forEach(el=>el.onclick=()=>{const id=el.dataset.related;$('#search').value='';$('#filter').value='';$('#savedOnly').checked=false;choose(id)});draw()}
$('#search').oninput=render;$('#filter').onchange=render;$('#savedOnly').onchange=render;$('#reset').onclick=()=>{$('#search').value='';$('#filter').value='';$('#savedOnly').checked=false;if($('#chain'))$('#chain').value='';selected=records[0].id;render()};if($('#chain'))$('#chain').onchange=render;render();
'''
def app(slug,title,desc,mode,records,edges=None,note='',group_label='groups',next_steps=None,build_steps=None,stack=None,data='',watchout='',paths=None):
    config=dict(slug=slug,mode=mode,records=records,edges=edges or [],groupLabel=group_label,paths=paths or [])
    body='<div class="row"><label>Search records<input id="search" type="search" placeholder="Name, theme or reference"></label><label>Filter<select id="filter"></select></label><button id="reset" type="button" class="secondary">Reset filters</button></div><div class="row"><label style="display:flex;gap:8px;align-items:center"><input id="savedOnly" type="checkbox"> Saved records only</label><span id="count" role="status"></span></div>'
    if paths:body+='<label>Compare transmission paths<select id="chain"><option value="">Both reports</option>'+''.join('<option value="'+p['id']+'">'+p['label']+'</option>' for p in paths)+'</select></label>'
    body+='<div class="notice">'+note+'</div><div class="explore-visual" id="visual"></div><div class="split"><div><h2>Explore records</h2><p class="muted">Select a record below. These buttons provide the keyboard alternative to the diagram.</p><div id="records" class="record-list"></div></div><article id="detail" class="evidence-panel" aria-live="polite"></article></div>'
    refs=list(dict.fromkeys((r['ref'],r['url']) for r in records))
    return build(slug,title,'Timelines & historical explorers' if mode in ['timeline','context'] else 'Knowledge graphs & relationship maps',desc,body,'const CONFIG='+json.dumps(config,ensure_ascii=False)+';\n'+SCRIPT,next_steps=next_steps,build_steps=build_steps,stack=stack,data=data,watchout=watchout,sources=refs,css=CSS)

seerah=[
rec('hira','First revelation at Hira','Makkah','Aisha describes the beginning of revelation and Khadijah\'s support.','The report describes seclusion, the angel\'s command and the return to Khadijah. It does not give a CE year.','Bukhari 3',b(3),date='c. 610 CE',short='Hira',limit='CE date is an approximate conventional chronology. The report is the evidence for the event.'),
rec('hijrah','Migration to Madinah','Migration','The migration connects Makkah and the new community in Madinah.','Aisha\'s long report describes preparations, Abu Bakr\'s companionship and the journey. Quran 9:40 refers to the cave.','Bukhari 3906',b(3906),date='622 CE / 1 AH',short='Hijrah',extra=q('9:40'),limit='Year labels use conventional chronology. This view does not reconstruct a precise route.'),
rec('qiblah','Change of qiblah','Madinah','Al-Bara describes the change of prayer direction toward the Kaabah.','His report places it after sixteen or seventeen months facing Jerusalem. The report preserves that uncertainty.','Bukhari 4486',b(4486),date='c. 624 CE / 2 AH',short='Qiblah',extra=q('2:144')),
rec('treaty','Treaty at Hudaybiyyah','Madinah','A detailed report describes negotiations and treaty conditions.','Read the full account for the terms, disagreements and subsequent events. A short timeline cannot represent every condition.','Bukhari 2731-2732',b(2731),date='c. 628 CE / 6 AH',short='Hudaybiyyah'),
rec('hajj','Farewell pilgrimage','Pilgrimage','Ibn Umar reports the Prophet\'s ﷺ pilgrimage and address.','This final sample event opens the pilgrimage report. No image or representation of the Prophet ﷺ appears in the demo.','Bukhari 4406',b(4406),date='632 CE / 10 AH',short='Pilgrimage')]
app('interactive-seerah-timeline','Interactive Seerah Timeline','Follow five sourced events, filter by setting, and inspect what each report establishes.','timeline',seerah,note='Five-event learning sample. Markers show order with equal spacing. CE dates are conventional approximations, not exact dates from each report.',group_label='settings',next_steps=['Add reviewed event ranges and alternative chronologies.','Add region maps, glossary entries and comparison views.','Let readers export a source-linked study trail.'],build_steps=['Create reviewed event records with date ranges and calendar labels.','Separate report evidence from editorial chronology.','Build timeline filters and accessible event lists.','Review dates and location claims before each content release.'],stack=['TypeScript and React for timeline controls.','SVG for the timeline; static JSON for reviewed event packs.','Optional Worker and D1 for private reading lists.'],data='Event: id, title, earliestDate, latestDate, calendar, region, summary. Evidence: eventId, sourceRef, edition, supportedClaim, reviewer. Store date confidence separately from report grading.',watchout='Historical sources differ in detail and chronology. Preserve source wording, mark date ranges, and avoid depictions of the Prophet Muhammad ﷺ.')

contexts=[rec('first','Beginning of revelation','Beginning','Aisha connects the Hira encounter with the opening recitation.','The report quotes the opening of Surah Al-Alaq. It does not establish an occasion for every verse in the surah.','Quran 96:1-3 and Bukhari 3',b(3),extra=q('96:1'),evidence='Aisha\'s report',limit='Scope: opening recitation. Do not apply this setting automatically to the whole surah.'),rec('direction','Change of prayer direction','Community','Al-Bara links the change of qiblah with Quran 2:144.','The same report relates concern about earlier prayers to Quran 2:143. It gives sixteen or seventeen months, not one exact duration.','Quran 2:143-144 and Bukhari 4486',b(4486),extra=q('2:144'),evidence='Al-Bara\'s report'),rec('mercy','A question about repentance','Repentance','Ibn Abbas reports a question from people with serious past sins.','The report associates their question with Quran 25:68 and 39:53. Read the surrounding repentance passages before drawing conclusions.','Quran 39:53 and Bukhari 4810',b(4810),extra=q('39:53'),evidence='Ibn Abbas\'s report'),rec('arafat','Revelation at Arafat','Pilgrimage','Umar identifies Friday at Arafat as the setting for the perfection-of-religion passage.','This report gives the setting for that part of Quran 5:3. It does not say that every statement in the verse was newly revealed together.','Quran 5:3 and Bukhari 45',b(45),extra=q('5:3'),evidence='Umar\'s report',limit='A reported setting is distinct from a claim about the last verse ever revealed.')]
app('revelation-context-explorer','Revelation Context Explorer','Inspect four reported settings and keep the passage, report and limits of the evidence in view.','context',contexts,note='Each card links a Quran passage to a specific report in Sahih al-Bukhari. Summaries are original paraphrases. This sample is not a complete asbab al-nuzul database.',next_steps=['Add report variants with scholarly grading and edition details.','Compare reported occasions with general thematic context.','Add a passage-range view and Arabic report text with licensed translations.'],build_steps=['Define passage ranges and claim-specific report links.','Have reviewers assess report scope and competing explanations.','Publish reviewed context records as versioned JSON.','Add side-by-side reports without collapsing differences.'],stack=['Astro with TypeScript for a mostly static evidence explorer.','Search index generated at build time.','D1 for moderated review queues only when needed.'],data='Passage: surah, startAyah, endAyah. ContextClaim: passageId, reportId, scope, uncertainty. Report: collection, number, edition, attribution, gradingSource, rights. Review: decision, reviewer, timestamp.',watchout='Many passages have no securely documented occasion of revelation. Leave gaps visible. A narrative association does not prove exclusive application.')

concepts=[rec('patience','Patience','Inner conduct','Quran 2:153 connects patience and prayer.','The theme label is an editorial study aid. It is not a claim that this verse exhausts the Quranic treatment of patience.','Quran 2:153',q('2:153'),short='Patience'),rec('gratitude','Gratitude','Inner conduct','Quran 14:7 links gratitude with increase.','Read the passage in its narrative context. The demo does not convert this promise into a financial prediction.','Quran 14:7',q('14:7'),short='Gratitude'),rec('justice','Justice','Social conduct','Quran 16:90 commands justice and good conduct.','This verse places justice beside ihsan and support for relatives. The relationship comes from co-occurrence in this verse.','Quran 16:90',q('16:90'),short='Justice'),rec('charity','Charity','Social conduct','Quran 2:261 uses a seed parable for spending in Allah\'s cause.','The label refers to this spending example. It does not replace the legal distinctions between zakat and voluntary giving.','Quran 2:261',q('2:261'),short='Charity'),rec('ihsan','Ihsan','Social conduct','Quran 16:90 mentions ihsan alongside justice.','English translations vary between good conduct, excellence and grace. Compare context before treating one English gloss as a full definition.','Quran 16:90',q('16:90'),short='Ihsan')]
edges=[dict(a='justice',b='ihsan',label='Both terms occur in Quran 16:90. This is a textual co-occurrence, not a synonym claim.',url=q('16:90'))]
app('quran-concept-atlas','Quran Concept Atlas','Explore five theme annotations and inspect the verse behind each relationship.','graph',concepts,edges,note='Solid lines show an explicitly sourced relationship. Dotted lines only place other sample topics nearby; they do not assert a relationship.',next_steps=['Add multiple verses per theme and reviewer explanations.','Distinguish word occurrence, thematic inference and tafsir attribution.','Add multi-theme intersections and a saved study trail.'],build_steps=['Define a controlled theme vocabulary with reviewer notes.','Link each annotation to exact verse ranges and evidence.','Precompute topic adjacency from reviewed annotations.','Test filters with Arabic and English search terms.'],stack=['TypeScript, React and SVG for selectable concept diagrams.','Static JSON plus a build-time search index.','Optional Worker and D1 for shared study collections.'],data='Concept: id, label, synonyms, definition. Annotation: conceptId, verseKey, relationType, explanation, reviewer. Edge: sourceConcept, targetConcept, evidenceVerse, relationType. Do not infer theological equivalence from proximity.',watchout='Theme assignment includes editorial interpretation. Label the relationship type and preserve the verse context. Do not use graph distance as religious authority.')

chain_names=[('umar','Umar ibn al-Khattab','Umar','Shared'),('alqama','Alqama ibn Waqqas','Alqama','Shared'),('muhammad','Muhammad ibn Ibrahim','Muhammad','Shared'),('yahya','Yahya ibn Said','Yahya','Shared'),('sufyan','Sufyan ibn Uyaynah','Sufyan','Bukhari 1'),('humaydi','Al-Humaydi','Al-Humaydi','Bukhari 1'),('malik','Malik ibn Anas','Malik','Bukhari 54'),('maslama','Abdullah ibn Maslama','Ibn Maslama','Bukhari 54')]
narrators=[rec(id,name,group,'Appears in the displayed intentions-report transmission path.','The Arabic isnad establishes the adjacent transmission links. The diagram reverses written isnad order to follow transmission toward the compiler.','Bukhari 1 and 54' if group=='Shared' else group,b(54 if group=='Bukhari 54' else 1),short=short,limit='A link here records this report\'s transmission. It is not an independent narrator evaluation.') for id,name,short,group in chain_names]
paths=[dict(id='one',label='Bukhari 1',ids=['umar','alqama','muhammad','yahya','sufyan','humaydi']),dict(id='fiftyfour',label='Bukhari 54',ids=['umar','alqama','muhammad','yahya','malik','maslama'])]
trans_edges=[]
for p in paths:
 for a,c in zip(p['ids'],p['ids'][1:]):
  if not any(e['a']==a and e['b']==c for e in trans_edges):trans_edges.append(dict(a=a,b=c,label='Transmission runs from '+next(r['name'] for r in narrators if r['id']==a)+' to '+next(r['name'] for r in narrators if r['id']==c)+'. See the Arabic isnad.',url=b(1 if p['id']=='one' else 54)))
app('hadith-narrator-network','Hadith Narrator Network','Compare two intentions-report paths and find the four narrators they share.','chains',narrators,trans_edges,paths=paths,note='Arrows run from earlier narrator toward later transmitter. The diagram stops at the compiler\'s named teacher. Both paths report from Umar, who attributes the saying to the Prophet ﷺ. Search filters the record list; the path selector controls the diagram.',next_steps=['Add exact Arabic transmission verbs and normalized narrator identities.','Attach scholarly narrator evaluations with explicit authorities.','Compare report variants without treating graph shape as authenticity proof.'],build_steps=['Transcribe reviewed isnads with collection and edition references.','Resolve narrator aliases through a human-reviewed identity table.','Store ordered paths and derive shared nodes.','Check each edge against its cited Arabic text.'],stack=['TypeScript and SVG for short transmission paths.','SQLite or D1 tables for narrators, reports and ordered chain steps.','Static graph exports for public read traffic.'],data='Narrator: id, canonicalName, aliases. Report: collection, hadithNumber, edition. ChainStep: reportId, position, narratorId, transmissionVerb. Evaluation: narratorId, authority, citation, wording. Keep route identity separate from report text.',watchout='The demo compares only Bukhari 1 and 54. It does not grade narrators or infer authenticity. Transmission wording needs specialist review.')

# Scholar view presents evidence-backed transmission relationships rather than unsourced biography.
scholars=[dict(r,summary='A named scholar or early transmitter in the intentions-report network.',detail='This record shows only relationships evidenced by Bukhari 1 or 54. The sample spans early transmitters and later hadith scholars; it does not claim a complete intellectual biography.',limit='An attested transmission supports this link. It does not by itself establish the duration or breadth of a teacher-student relationship.') for r in narrators]
scholar_notes={
'umar':('Source narrator in both reports.', 'Alqama transmits this report from Umar. This sample places Umar at the start of the displayed human transmission path.'),
'alqama':('A shared transmitter before the two routes divide.', 'Both displayed isnads place Alqama between Umar and Muhammad ibn Ibrahim. The network shows those two evidenced links.'),
'muhammad':('A shared link between Alqama and Yahya.', 'Both Arabic isnads name Muhammad ibn Ibrahim after Yahya and before Alqama in written collector-to-source order.'),
'yahya':('The shared teacher at the displayed branch point.', 'Bukhari 1 places Sufyan after Yahya in transmission order. Bukhari 54 supplies a second branch through Malik.'),
'sufyan':('A named transmitter on the Bukhari 1 route.', 'The first report records Al-Humaydi receiving the report from Sufyan, who receives it from Yahya. Those links define this sample profile.'),
'humaydi':("The compiler's named teacher in Bukhari 1.", 'The Arabic report opens with Al-Humaydi and then Sufyan. This profile records that transmission relationship without inferring a complete teaching career.'),
'malik':('A named transmitter on the Bukhari 54 route.', 'Bukhari 54 records Abdullah ibn Maslama receiving the report from Malik, with Yahya before Malik in transmission order.'),
'maslama':("The compiler's named teacher in Bukhari 54.", 'The Arabic report opens with Abdullah ibn Maslama and then Malik. This sample shows the relationship attested by that report.')}
for r in scholars:
 r['summary'],r['detail']=scholar_notes[r['id']]
app('islamic-scholars-network','Islamic Scholars Network','Explore a small evidence-backed learning network through named transmissions across generations.','graph',scholars,trans_edges,note='Solid lines show a documented transmission involving the selected person. Dotted lines provide layout only. This starter network covers early Islamic scholarship; later-century expansion needs reviewed biographies.',next_steps=['Add biographical dates and cities with edition-specific citations.','Distinguish direct study, textual influence and disputed relationships.','Expand across centuries with regional and discipline filters.'],build_steps=['Start with relationships that have an explicit primary-source citation.','Create reviewed person identities and alias records.','Record relationship type, scope and evidence separately.','Add biographies only after source and date review.'],stack=['TypeScript and React for filters and detail panels.','SVG for small graphs; Cytoscape.js when reviewed networks grow.','D1 with indexed people and edge tables; cached static snapshots.'],data='Person: id, names, birthRange, deathRange, places. Relationship: sourcePerson, targetPerson, type, evidenceId, confidence, scope. Evidence: work, edition, pageOrHadith, supportedClaim. Store intellectual influence separately from direct transmission.',watchout='A shared period or city does not prove direct study. Use explicit citations for each relationship. The demo deliberately leaves unsourced biographical fields empty.')

places=[rec('bakkah','Bakkah / Makkah','Named location','Quran 3:96 names Bakkah in connection with the first House.','The familiar Makkah identification is a traditional identification. The verse supplies no modern coordinates.','Quran 3:96',q('3:96'),x=565,y=220,short='Bakkah',limit='Regional marker only. The map is not suitable for navigation.'),rec('egypt','Egypt','Named region','Quran 12:99 names Egypt in the Yusuf narrative.','The verse identifies a region. It does not identify the palace, city or travel route shown in some reconstructions.','Quran 12:99',q('12:99'),x=275,y=100,short='Egypt',limit='Region-level identification. No precise narrative site is asserted.'),rec('sinai','Mount Sinai','Traditional region','Quran 95:2 refers to Mount Sinai.','This sample places the traditional Sinai region schematically. It does not resolve competing identifications of the specific mountain.','Quran 95:2',q('95:2'),x=385,y=105,short='Sinai',limit='Specific mountain identification is disputed; the pin is approximate.'),rec('cave','Cave of the sleepers','Unlocated in text','Quran 18:9 introduces the companions of the cave.','The passage does not name a modern site. Proposed locations should remain claims with separate evidence, not confident pins.','Quran 18:9',q('18:9'),short='Cave: unlocated',limit='The lower marker is an unlocated-record tray. It is not a geographic position.')]
app('quranic-places-atlas','Quranic Places Atlas','Connect four Quranic place references with region-level context and visible geographic uncertainty.','map',places,note='Schematic geography, not a geographic projection. Pins are approximate. The unlocated record sits in a separate tray and asserts no coordinates.',group_label='identification types',next_steps=['Add evidence layers for proposed identifications.','Show confidence regions instead of precise pins for uncertain sites.','Add reviewed historical place names and passage comparisons.'],build_steps=['Separate Quranic place references from proposed modern identifications.','Record evidence and uncertainty for each identification.','Generate an offline SVG regional map.','Add map tiles only when scale and licensing justify them.'],stack=['TypeScript and SVG for the first offline atlas.','GeoJSON plus MapLibre for later interactive geography.','Static JSON and CDN caching; D1 only for moderation.'],data='PlaceReference: id, textName, verseKeys. Identification: referenceId, modernName, geometry, precision, status, evidence. Preserve unknown geometry as null. Never map an unlocated reference to a guessed point.',watchout='The Quran often names regions without precise coordinates. A modern marker can imply more certainty than the source supports. Keep identification evidence visible.')

terms=[rec('iman','Iman','Faith and conduct','A common English gloss is faith or belief.','Quran 8:2 links the believers\' response to remembrance and recitation with trust in their Lord. The gloss is introductory.','Quran 8:2',q('8:2'),short='Iman'),rec('tawakkul','Tawakkul','Faith and conduct','A common English gloss is reliance on Allah.','Quran 3:159 places reliance after consultation and resolve. Quran 8:2 also mentions trust in the description of believers.','Quran 3:159',q('3:159'),short='Tawakkul',extra=q('8:2')),rec('ihsan','Ihsan','Ethical conduct','In Quran 16:90, ihsan appears alongside justice.','Translations use several English terms. This map uses good conduct as an introductory gloss, not an exhaustive theological definition.','Quran 16:90',q('16:90'),short='Ihsan'),rec('adl','Adl','Ethical conduct','A common English gloss is justice.','Quran 16:90 commands justice and ihsan. These terms share a verse but are not interchangeable definitions.','Quran 16:90',q('16:90'),short='Adl'),rec('taqwa','Taqwa','Faith and conduct','A common English gloss is mindfulness of Allah or God-consciousness.','Quran 2:197 connects provision for the journey with taqwa. English glosses cannot represent every contextual use.','Quran 2:197',q('2:197'),short='Taqwa')]
term_edges=[dict(a='iman',b='tawakkul',label='Quran 8:2 includes trust in Allah in its description of believers. The relationship is contextual.',url=q('8:2')),dict(a='adl',b='ihsan',label='Quran 16:90 commands both justice and ihsan. Co-occurrence does not mean the terms are synonyms.',url=q('16:90'))]
app('islamic-terminology-map','Islamic Terminology Map','Select a term, compare its introductory gloss, and follow relationships grounded in specific passages.','graph',terms,term_edges,note='Solid lines have passage-specific evidence. Dotted lines show other glossary entries only. Definitions are introductory English glosses and require context.',next_steps=['Add Arabic spelling, pronunciation and contextual usage examples.','Compare attributed scholarly definitions rather than merging them.','Add contrast cards and retrieval-practice exercises.'],build_steps=['Define each term with a reviewed scope and source.','Create typed relationships linked to exact passages.','Support Arabic normalization without changing displayed text.','Review English glosses with Arabic-language specialists.'],stack=['Astro or React with TypeScript for the glossary explorer.','Static JSON, an Arabic-aware search index and SVG diagrams.','Optional IndexedDB for saved vocabulary and practice history.'],data='Term: id, Arabic, transliteration, aliases. Sense: termId, gloss, context, authority. Relationship: fromSense, toSense, type, passage, reviewer. Store multiple senses instead of one universal English definition.',watchout='A term can have several contextual senses. Graph proximity and English glosses do not establish doctrinal equivalence. Cite the sense and relationship separately.')
print('Built 7 explorer demos.')
